// js
// ctx.entry.quantity is the substitute leave taken; each hour replaces the extra 25% of four overtime hours.
const entry = get(ctx, 'entry', {});
const hourly = ctx.hour_rate;
const hours = Number(get(entry, 'quantity', 0)) * ctx.lookup.overtime_hours_per_substitute_hour;
return hours * hourly * ctx.lookup.multiplier;
